'use client'

import * as React from 'react'

import { useStrings, type StringsOverrides } from './strings'
import { ChevronGlyph, CrossGlyph } from './glyphs'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Composer, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './composer.css'

// The shared rule sets, so the theme's action face and press gesture reach the
// send control. GSUI-118: the file shipped with the tokens and nothing imported
// it, so the classes matched nothing in a real install.
import './gamestage-primitives.css'

/**
 * Composer: the field a player types into, saying the rule before they can
 * break it.
 *
 * Specimen 6c draws four states and 6f draws the reply half. Three of the four
 * stop a player posting and each stops them for a different reason, so the
 * state is an enum rather than a disabled flag: a control that is merely
 * disabled tells a player nothing about when it will not be. `limited` counts
 * down in seconds for that reason, because "slow mode" is a phrase, not a time.
 *
 * The field keeps its text while a message is being screened. A refusal then
 * costs the player nothing to retype, which is the difference between a rule
 * they can live with and one that eats their words.
 *
 * It screens nothing, holds no rate limit and starts no clock. `busy` and
 * `retryIn` are the host's, and a host counting a limit down re-renders with a
 * smaller number.
 */

export type ComposerState = 'idle' | 'typing' | 'screening' | 'limited'

export interface ComposerReplyTo {
  /** Who is being replied to, as the host spells the name. */
  author: string
  /** What they said. One line, clipped: a quote is a reminder, not the message. */
  text: string
}

export interface ComposerProps extends Omit<React.HTMLAttributes<HTMLFormElement>, 'onSubmit'> {
  /** Per-instance vocabulary, merged over the provider. */
  strings?: StringsOverrides

  /** What is in the field. Controlled: the host owns the text. */
  value: string
  /** Every keystroke. */
  onValueChange: (value: string) => void
  /** The player pressed send, or pressed Enter. */
  onSubmit: () => void

  /** What the field says when it is empty. */
  placeholder?: string
  /** The send control's accessible name. */
  sendLabel?: string
  /** The field's accessible name. */
  label?: string

  /**
   * The character limit. The counter appears at 200 left and turns warning at
   * 20; before that it is noise. Absent and there is no limit and no counter.
   */
  maxLength?: number

  /** The message is with the screen. The field keeps the text. */
  busy?: boolean
  /**
   * Seconds until the player may post again. Anything above nought is the rate
   * limit, and the composer counts what it is given rather than counting down
   * itself.
   */
  retryIn?: number

  /** The message this one answers. One quote, one level deep, and no further. */
  replyTo?: ComposerReplyTo
  /** The player dropped the reply target. Absent and the quote cannot be dropped. */
  onCancelReply?: () => void
}

/** The counter appears here, and not before: 200 characters of silence. */
const COUNTER_AT = 200

/** And turns warning here, which is about a sentence from the end. */
const WARNING_AT = 20

export function Composer(props: ComposerProps) {
  const { strings, ...componentProps } = props
  const copy = useStrings(strings)

  const {
    value,
    onValueChange,
    onSubmit,
    placeholder = copy['composer.placeholder'],
    sendLabel = copy['composer.sendLabel'],
    label = copy['composer.label'],
    maxLength,
    busy = false,
    retryIn = 0,
    replyTo,
    onCancelReply,
    className,
    ...rest
  } = componentProps

  const limited = retryIn > 0
  const state: ComposerState =
    limited ? 'limited'
    : busy ? 'screening'
    : value.length > 0 ? 'typing'
    : 'idle'

  const left = maxLength === undefined ? undefined : maxLength - value.length
  const counting = left !== undefined && left <= COUNTER_AT
  const warning = left !== undefined && left <= WARNING_AT
  const counterId = React.useId()

  // Nothing to send, or nothing may be sent. Three causes, one control state,
  // because the reason is on screen beside it rather than inside it.
  const blocked = limited || busy || value.trim().length === 0

  return (
    <form
      {...rest}
      className={['gs-composer', className].filter(Boolean).join(' ')}
      data-gs-component="composer"
      data-gs-composer={state}
      onSubmit={event => {
        event.preventDefault()
        if (!blocked) onSubmit()
      }}
    >
      {/* The reply target sits inside the composer and can be dropped. It grows
          the composer once, by one row, and it happens because the player asked
          for it: the one push the frame allows. */}
      {replyTo !== undefined ? (
        <div className="gs-composer__reply" data-gs-scope="composer" data-gs-part="row">
          <span className="gs-composer__reply-author" data-gs-scope="composer" data-gs-part="label">
            {replyTo.author}
          </span>
          <span className="gs-composer__reply-text" data-gs-scope="composer" data-gs-part="detail">
            {replyTo.text}
          </span>
          {onCancelReply ? (
            <button
              type="button"
              className="gs-composer__cancel gs-action-type gs-pressable"
              data-gs-scope="composer" data-gs-part="dismiss"
              aria-label={copy['composer.cancelReply']}
              onClick={onCancelReply}
            >
              <CrossGlyph />
            </button>
          ) : null}
        </div>
      ) : null}

      <div className="gs-composer__row">
        {state === 'screening' || state === 'limited' ? (
          <p className="gs-composer__note" data-gs-scope="composer" data-gs-part="note">
            <span
              className="gs-composer__busy"
              data-gs-scope="composer" data-gs-part="busy"
              // Screening turns, because something is happening to the message.
              // A rate limit waits, and a waiting square that spun would say
              // the room was working on it.
              data-gs-motion={state === 'screening' ? 'rays' : undefined}
              data-gs-animates={state === 'screening' ? 'motion' : 'emphasis'}
              aria-hidden="true"
            />
            {state === 'screening' ? copy['composer.screening'] : copy['composer.limited'](retryIn)}
          </p>
        ) : (
          <input
            className="gs-composer__field"
            data-gs-scope="composer" data-gs-part="control"
            type="text"
            value={value}
            onChange={event => onValueChange(event.target.value)}
            maxLength={maxLength}
            placeholder={placeholder}
            aria-label={label}
            aria-describedby={counting ? counterId : undefined}
          />
        )}

        <button
          type="submit"
          className="gs-composer__send gs-action-type gs-pressable"
          data-gs-scope="composer" data-gs-part="commit"
          data-gs-disabled={blocked ? 'true' : undefined}
          disabled={blocked}
          aria-label={sendLabel}
        >
          <span className="gs-composer__send-glyph" aria-hidden="true">
            {/* Up, as 6c draws it; the triangle read as a warning sign. */}
            <ChevronGlyph direction="up" />
          </span>
        </button>
      </div>

      {counting && left !== undefined ? (
        <p
          id={counterId}
          className="gs-composer__counter"
          data-gs-scope="composer" data-gs-part="value"
          data-gs-value={left}
          data-gs-max={maxLength}
          data-gs-warning={warning ? 'true' : undefined}
          data-gs-animates="emphasis"
        >
          {copy['composer.left'](left)}
          {warning ? (
            <span className="gs-composer__announcement" data-gs-scope="composer" data-gs-part="announcement">
              {copy['composer.going']}
            </span>
          ) : null}
        </p>
      ) : null}
    </form>
  )
}

/* Composer. Every value comes from a token; nothing here is a literal colour.

   Specimen 6c draws the four states at 48px, with 44 as the floor, and 6f
   draws the reply quote inside the field. The field and the send control are
   one row that keeps its height in every state, so the thing under the
   player's thumb does not move when the room rate-limits them. */

.gs-composer {
  display: flex;
  flex-direction: column;
  gap: var(--gs-space-2);
  padding: var(--gs-space-gap) var(--gs-space-inset);

  background: var(--gs-color-surface);
  border-top: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
}

.gs-composer__row {
  display: flex;
  align-items: center;
  gap: var(--gs-space-2);
}

/* -- the field ------------------------------------------------------------- */

.gs-composer__field,
.gs-composer__note {
  flex: 1 1 auto;
  min-width: 0;
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: var(--gs-space-2);
  height: var(--gs-size-touch-min);
  margin: 0;
  padding: 0 var(--gs-space-inset);

  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-body-font-size);
  font-weight: var(--gs-type-body-font-weight);

  color: var(--gs-color-ink);
  background: var(--gs-color-background);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
}

.gs-composer__field::placeholder { color: var(--gs-color-muted); }

.gs-composer__field:focus-visible {
  outline: none;
  border-color: var(--gs-color-selected);
}

/* Being checked: a dashed edge, the same mark screening draws on a message, so
   the two halves of one wait look like one thing. */
.gs-composer[data-gs-composer='screening'] .gs-composer__note {
  border-style: dashed;
  border-color: var(--gs-color-edge-high);
  color: var(--gs-color-ink-secondary);
}

/* Rate limited: the flat, unavailable treatment, with the seconds in it. */
.gs-composer[data-gs-composer='limited'] .gs-composer__note {
  color: var(--gs-color-disabled-ink);
  background: var(--gs-color-disabled);
}

.gs-composer__busy {
  display: inline-block;
  flex: none;
  box-sizing: border-box;
  width: var(--gs-size-icon-utility);
  height: var(--gs-size-icon-utility);
  border: var(--gs-stroke-selected, var(--gs-stroke-hairline)) solid currentColor;
  border-radius: var(--gs-radius-sm);
}

.gs-composer[data-gs-composer='screening'] .gs-composer__busy {
  border-top-color: transparent;
  border-radius: var(--gs-radius-full);
}

/* -- send ------------------------------------------------------------------ */

/* 48px, round, and it goes flat rather than away: a control that disappeared
   when there was nothing to send would move the field every time the player
   emptied it. */
.gs-composer__send {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  width: var(--gs-size-touch-min);
  height: var(--gs-size-touch-min);
  padding: 0;
  cursor: pointer;

  color: var(--gs-color-on-accent);
  background: var(--gs-color-interactive);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
  box-shadow: var(--gs-depth-raised);
}

.gs-composer__send[data-gs-disabled='true'] {
  cursor: not-allowed;
  color: var(--gs-color-disabled-ink);
  background: var(--gs-color-disabled);
  box-shadow: none;
}

.gs-composer__send:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: 3px;
}

.gs-composer__send-glyph {
  display: inline-flex;
  font-size: var(--gs-size-icon-control);
}

/* -- the counter ----------------------------------------------------------- */

/* Right-aligned under the field, clear of the send control, as drawn. */
.gs-composer__counter {
  align-self: flex-end;
  margin: 0;
  padding-right: calc(var(--gs-size-touch-min) + var(--gs-space-2));

  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-caption-font-size);
  font-weight: var(--gs-type-label-font-weight);

  color: var(--gs-color-muted);
  transition: color var(--gs-motion-emphasis) var(--gs-motion-ease-emphasis);
}

.gs-composer__counter[data-gs-warning='true'] { color: var(--gs-color-warning); }

/* The word a screen reader gets in place of the colour change. */
.gs-composer__announcement {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
}

/* -- the reply target ------------------------------------------------------ */

/* One quote, one line, clipped. It grows the composer once, by one row, and
   only because the player chose to reply. */
.gs-composer__reply {
  display: flex;
  align-items: center;
  gap: var(--gs-space-2);
  padding: var(--gs-space-1) var(--gs-space-gap);

  background: var(--gs-color-background);
  border-left: var(--gs-stroke-selected, var(--gs-stroke-hairline)) solid var(--gs-color-opponent);
  border-radius: var(--gs-radius-sm);
}

.gs-composer__reply-author {
  flex: none;
  font-family: var(--gs-type-label-font-family);
  font-size: var(--gs-type-caption-font-size);
  font-weight: var(--gs-type-label-font-weight);
  color: var(--gs-color-opponent);
}

.gs-composer__reply-text {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  white-space: nowrap;
  text-overflow: ellipsis;

  font-family: var(--gs-type-body-font-family);
  font-size: var(--gs-type-caption-font-size);
  color: var(--gs-color-ink-secondary);
}

.gs-composer__cancel {
  flex: none;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  box-sizing: border-box;
  width: var(--gs-size-control-small);
  height: var(--gs-size-control-small);
  padding: 0;
  cursor: pointer;

  font-size: var(--gs-size-icon-utility);
  color: var(--gs-color-ink-secondary);
  background: var(--gs-color-surface-raised);
  border: var(--gs-stroke-ui, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  border-radius: var(--gs-radius-full);
}

.gs-composer__cancel:hover { color: var(--gs-color-ink); }

.gs-composer__cancel:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: 3px;
}
